const context = $('Validar Contexto').first().json;
const formatMoney = (value) => {
  if (value === null || value === undefined || value === '') return 'nao informado';
  const numberValue = Number(value);
  if (Number.isFinite(numberValue)) return `R$ ${numberValue.toFixed(2).replace('.', ',')}`;
  return String(value);
};
const formatMarketplace = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'shopee') return 'Shopee';
  return String(value || 'Marketplace').trim();
};
const discountPercent = (price, referencePrice) => {
  const current = Number(price);
  const reference = Number(referencePrice);
  if (!Number.isFinite(current) || !Number.isFinite(reference) || reference <= current || reference <= 0) return 0;
  return Math.round(((reference - current) / reference) * 100);
};
const formatRating = (value) => {
  const rating = Number(value);
  if (Number.isFinite(rating)) return rating.toFixed(1).replace('.', ',');
  return 'nao informada';
};
return items.map((item, index) => {
  const offer = item.json;
  const discount = discountPercent(offer.price, offer.reference_price);
  const messageText = `\u{1F525} ${offer.product_name}

\u{1F4B5} ${formatMoney(offer.price)}
\u{1F3F7}\u{FE0F} ${discount}% OFF
\u{2B50} Avalia\u{00E7}\u{00E3}o: ${formatRating(offer.rating)}/5
\u{2705} Link do produto:
${offer.offer_link}

\u{1F3EA} Loja: ${formatMarketplace(offer.marketplace)}
\u{1F39F}\u{FE0F} Resgate o cupom desta p\u{00E1}gina:
${context.coupon_url}
(an\u{00FA}ncio)`;
  return {
    json: {
      ...context,
      ...offer,
      coupon_url: context.coupon_url,
      discount_percent: discount,
      manifest_item_number: offer.manifest_item_number ?? index + 1,
      send_sequence_number: offer.send_sequence_number ?? offer.manifest_item_number ?? index + 1,
      message_text: messageText,
      manifest_created_at: new Date().toISOString(),
    }
  };
});

const item = $json;
const allowed = new Set(item.allowed_targets || []);
const targetAllowed = allowed.has(item.target);
