const item = items[0].json;
const cleanText = (value, field) => {
  const text = String(value || '').trim();
  if (!/^[a-z0-9][a-z0-9_-]{1,80}$/i.test(text)) {
    throw new Error(`${field} fora do contrato MVP: ${text}`);
  }
  return text;
};
const parseDelay = (value, field, fallback) => {
  const numeric = Number(value ?? fallback);
  if (!Number.isInteger(numeric) || numeric < 0 || numeric > 600) {
    throw new Error(`${field} fora do contrato MVP: ${value}`);
  }
  return numeric;
};
const profile = cleanText(item.profile, 'profile');
const marketplace = cleanText(item.marketplace, 'marketplace');
const target = cleanText(item.target, 'target');
const channelAdapter = cleanText(item.channel_adapter, 'channel_adapter');
const limit = Number(item.limit || 1);
if (!Number.isInteger(limit) || limit < 1 || limit > 20) {
  throw new Error(`limit fora do contrato MVP: ${item.limit}`);
}
const dryRun = item.dry_run === true || item.dry_run === 'true' || item.dry_run === 1 || item.dry_run === '1';
const allowedTargets = String(item.allowed_targets_csv || '')
  .split(',')
  .map((targetItem) => targetItem.trim())
  .filter(Boolean);
if (allowedTargets.length === 0) {
  throw new Error('allowed_targets_csv obrigatorio');
}
const sendDelaySecondsMin = parseDelay(item.send_delay_seconds_min, 'send_delay_seconds_min', 45);
const sendDelaySecondsMax = parseDelay(item.send_delay_seconds_max, 'send_delay_seconds_max', 90);
if (sendDelaySecondsMax < sendDelaySecondsMin) {
  throw new Error('send_delay_seconds_max deve ser maior ou igual a send_delay_seconds_min');
}
const artifactGeneratedAt = item.artifact_generated_at || new Date().toISOString();
const claimToken = cleanText(item.run_id, 'run_id');
const sqlText = (value) => `'${String(value).replace(/'/g, "''")}'`;
const previewQuery = `select
  null::uuid as dispatch_plan_id,
  ready.profile,
  ready.marketplace,
  ready.stable_key,
  ready.item_id,
  ready.product_name,
  ready.offer_link,
  ready.image_url,
  ready.price,
  ready.reference_price,
  ready.rating,
  ready.sales_count,
  ready.primary_subniche,
  ready.commercial_score,
  ready.score_reasons,
  ready.rank_profile,
  ready.rank_subniche,
  ready.selection_bucket,
  ready.selection_reason,
  ready.planned_date,
  ready.planned_hour,
  ready.slot_sequence,
  ready.daily_sequence,
  ready.planned_at
from offers.v_daily_dispatch_ready ready
where ready.is_ready_for_dispatch
  and ready.profile = ${sqlText(profile)}
  and ready.marketplace = ${sqlText(marketplace)}
  and ready.planned_date = (now() at time zone 'America/Sao_Paulo')::date
  and ready.planned_hour = extract(hour from now() at time zone 'America/Sao_Paulo')::integer
order by ready.slot_sequence
limit ${limit};`;
const claimQuery = `with next_slots as (
  select plan.dispatch_plan_id
  from offers.daily_dispatch_plan plan
  join offers.v_daily_dispatch_ready ready using (dispatch_plan_id)
  where ready.is_ready_for_dispatch
    and ready.profile = ${sqlText(profile)}
    and ready.marketplace = ${sqlText(marketplace)}
    and ready.planned_date = (now() at time zone 'America/Sao_Paulo')::date
    and ready.planned_hour = extract(hour from now() at time zone 'America/Sao_Paulo')::integer
  order by ready.slot_sequence
  for update of plan skip locked
  limit ${limit}
), claimed as (
  update offers.daily_dispatch_plan plan
  set dispatch_status = 'claimed',
      claim_token = ${sqlText(claimToken)},
      claimed_at = now(),
      updated_at = now()
  from next_slots
  where plan.dispatch_plan_id = next_slots.dispatch_plan_id
  returning plan.dispatch_plan_id
)
select
  ready.dispatch_plan_id,
  ready.profile,
  ready.marketplace,
  ready.stable_key,
  ready.item_id,
  ready.product_name,
  ready.offer_link,
  ready.image_url,
  ready.price,
  ready.reference_price,
  ready.rating,
  ready.sales_count,
  ready.primary_subniche,
  ready.commercial_score,
