  ready.selection_bucket,
  ready.selection_reason,
  ready.planned_date,
  ready.planned_hour,
  ready.slot_sequence,
  ready.daily_sequence,
  ready.planned_at
from claimed
join offers.v_daily_dispatch_ready ready using (dispatch_plan_id)
order by ready.slot_sequence;`;
const rankingQuery = dryRun ? previewQuery : claimQuery;
