const shouldSend =
  item.channel_adapter === 'whatsapp' &&
  item.target_allowed === true &&
  item.dry_run === false &&
  item.send_result === 'ready_for_real_channel_node';

const normalizeChatId = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return null;
  if (raw.endsWith('@c.us') || raw.endsWith('@g.us') || raw.endsWith('@lid')) return raw;
  const digits = raw.replace(/[^\d]/g, '');
  if (digits.length >= 12 && digits.length <= 15) return `${digits}@c.us`;
  return null;
};

const normalizeImageUrl = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return null;
  if (!/^https?:\/\//i.test(raw)) return null;
  return raw;
};

const filenameFrom = (value) => {
  const suffix = String(value || 'oferta').replace(/[^a-z0-9_-]/gi, '').slice(0, 80) || 'oferta';
  return `oferta-${suffix}.jpg`;
};

const normalizeDelay = (value, fallback) => {
  const numeric = Number(value ?? fallback);
  return Number.isFinite(numeric) && numeric >= 0 ? Math.floor(numeric) : fallback;
};

const randomDelay = (minValue, maxValue) => {
  if (maxValue <= minValue) return minValue;
  return Math.floor(Math.random() * (maxValue - minValue + 1)) + minValue;
};

const sequenceNumber = Number(item.send_sequence_number || item.manifest_item_number || 1);
const delayMin = normalizeDelay(item.send_delay_seconds_min, 45);
const delayMax = Math.max(delayMin, normalizeDelay(item.send_delay_seconds_max, 90));
const waitSeconds = shouldSend && sequenceNumber > 1 ? randomDelay(delayMin, delayMax) : 0;
const wahaChatId = normalizeChatId(item.target_chat_id || item.target);
const wahaImageUrl = normalizeImageUrl(item.image_url);

if (shouldSend && !wahaChatId) {
  return {
    json: {
      ...item,
      waha_should_send: false,
      waha_chat_id: null,
      waha_image_url: wahaImageUrl,
      waha_send_delay_seconds: 0,
      adapter_status: 'adapter_missing_chat_id',
      send_result: 'adapter_missing_chat_id',
      delivery_status: 'failed',
      sent_at: null,
    },
  };
}

if (shouldSend && !wahaImageUrl) {
  return {
    json: {
      ...item,
      waha_should_send: false,
      waha_chat_id: wahaChatId,
      waha_image_url: null,
      waha_send_delay_seconds: 0,
      adapter_status: 'adapter_missing_image_url',
      send_result: 'adapter_missing_image_url',
      delivery_status: 'failed',
      sent_at: null,
    },
  };
}

return {
  json: {
    ...item,
    waha_should_send: shouldSend,
    waha_chat_id: shouldSend ? wahaChatId : null,
    waha_image_url: shouldSend ? wahaImageUrl : null,
    waha_image_filename: shouldSend ? filenameFrom(item.item_id || item.stable_key) : null,
    waha_send_delay_seconds: waitSeconds,
  },
};

const original = $('Preparar Envio WAHA').item.json;
const response = $json || {};

const messageId =
  response.id?._serialized ||
  response._data?.id?._serialized ||
  response.id?.id ||
  null;

const ack = response.ack ?? response._data?.ack ?? null;
