return [{ json: { ...context, message_folder_id: matches[0].json.id, message_folder_url: matches[0].json.webViewLink || null, static_ready: true } }];

const context = $('Validar Pasta msg_XXX').first().json;
const copyMatches = items.filter((item) => item.json?.name === 'copy.txt' && item.json?.mimeType === 'text/plain' && item.json?.id);
const imageMatches = items.filter((item) => item.json?.name === 'image.jpg' && item.json?.mimeType === 'image/jpeg' && item.json?.id);
